def interpreta(riga):
    match riga.split():
        case ["F", F, "a", a]:
            return ("F", float(F), float(a))
        case ["q", q, "da", a, "a", b]:
            return ("q", float(q), float(a), float(b))
        case ["q", q]:
            return ("q", float(q), 0.0, None)
        case _:
            raise ValueError(f"comando non valido: {riga!r}")


def leggi_carichi(testo):
    out = []
    for riga in testo.splitlines():
        riga = riga.split("#")[0].strip()
        if riga:
            out.append(interpreta(riga))
    return out
